(function(){function preferredTheme(){try{const savedTheme=localStorage.getItem('theme');if(savedTheme==='light'||savedTheme==='dark'){return savedTheme;}}catch(error){return'light';}
return window.matchMedia&&window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light';}
function setTheme(theme){const normalizedTheme=theme==='dark'?'dark':'light';document.documentElement.setAttribute('data-theme',normalizedTheme);if(typeof window.applyThemePictures==='function'){window.applyThemePictures(normalizedTheme);}updateThemeIcon(normalizedTheme);}
window.toggleTheme=function(){const currentTheme=document.documentElement.getAttribute('data-theme')||preferredTheme();const nextTheme=currentTheme==='dark'?'light':'dark';try{localStorage.setItem('theme',nextTheme);}catch(error){}
setTheme(nextTheme);};window.updateThemeIcon=function(theme){const nextIcon=theme==='dark'?'☀️':'🌙';document.querySelectorAll('.theme-toggle').forEach(function(button){const icon=button.querySelector('.theme-toggle__icon');if(icon){icon.textContent=nextIcon;}else{button.textContent=nextIcon;button.setAttribute('aria-label','Тема оформления');}button.removeAttribute('title');});};setTheme(preferredTheme());document.addEventListener('DOMContentLoaded',function(){setTheme(document.documentElement.getAttribute('data-theme')||preferredTheme());});})();
